{
  "claims": [
    {
      "claim_text": "Because transaction IDs are only 32 bits wide, the XID space holds about 4 billion values, and every normal XID has roughly two billion older and two billion newer XIDs.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that transaction IDs have limited size (32 bits) and that the normal XID space is circular with two billion older and two billion newer XIDs.",
      "citations": [
        {
          "index": 0,
          "quote": "transaction IDs have limited size (32 bits)"
        },
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_text": "Every table must be vacuumed at least once every two billion transactions; running past that without vacuuming means permanent, unrecoverable data loss.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages say that vacuuming every table at least once every two billion transactions is necessary to avoid catastrophic data loss, and that going longer could result in data loss.",
      "citations": [
        {
          "index": 0,
          "quote": "it is necessary to vacuum every table in every database at least once every two billion transactions."
        },
        {
          "index": 2,
          "quote": "If it were to go unvacuumed for longer than that, data loss could result."
        }
      ]
    },
    {
      "claim_text": "With the default autovacuum_freeze_max_age of 200 million transactions, the anti-wraparound autovacuum kicks in after only about 10% of that two-billion window.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state the default is 200 million transactions, and since the window is two billion, 200 million is 10% of that.",
      "citations": [
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        },
        {
          "index": 0,
          "quote": "at least once every two billion transactions"
        }
      ]
    },
    {
      "claim_text": "The effective maximum for vacuum_freeze_table_age is 95% of autovacuum_freeze_max_age, so with the default it can be at most 180 million.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state the effective maximum is 0.95 * autovacuum_freeze_max_age, and 0.95 * 200 million = 190 million, not 180 million. The claim says 180 million, which is incorrect.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        }
      ]
    },
    {
      "claim_text": "If autovacuum still fails, warnings start when the oldest XIDs are forty million transactions from wraparound and new XIDs are refused once fewer than three million remain, leaving a 37-million-transaction window between the first warning and the hard stop.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages mention warnings at forty million transactions from wraparound and refusal at fewer than three million, which gives a 37-million window.",
      "citations": [
        {
          "index": 6,
          "quote": "when the database's oldest XIDs reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_text": "Once XID assignment stops, no new transactions of any kind can be started.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages state that only read-only transactions can be started, not that no new transactions of any kind can be started.",
      "citations": [
        {
          "index": 8,
          "quote": "only read-only transactions can be started"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "Autovacuum relies on the statistics collection facility, so if track_counts is off, autovacuum cannot be used.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that autovacuum checks use the statistics collection facility and therefore cannot be used unless track_counts is set to true.",
      "citations": [
        {
          "index": 1,
          "quote": "These checks use the statistics collection facility; therefore, autovacuum cannot be used unless track_counts is set to true."
        }
      ]
    },
    {
      "claim_text": "Turning track_counts on is by itself enough for autovacuum to work.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage only says autovacuum cannot be used unless track_counts is true, but does not state that this alone is sufficient for autovacuum to work.",
      "citations": []
    },
    {
      "claim_text": "Even when autovacuum is disabled, PostgreSQL still invokes it on tables that might contain unfrozen rows with XIDs older than autovacuum_freeze_max_age.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than autovacuum_freeze_max_age, and this happens even if autovacuum is disabled.",
      "citations": [
        {
          "index": 0,
          "quote": "To ensure that this does not happen, autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age. (This will happen even if autovacuum is disabled.)"
        }
      ]
    },
    {
      "claim_text": "The launcher tries to start one worker per database every autovacuum_naptime seconds, so with 4 databases and autovacuum_naptime set to 60 seconds, a new worker starts about every 15 seconds.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says the launcher attempts to start one worker within each database every autovacuum_naptime seconds, and if there are N databases, a new worker is launched every autovacuum_naptime/N seconds. With N=4 and naptime=60, that is 15 seconds.",
      "citations": [
        {
          "index": 2,
          "quote": "The launcher will distribute the work across time, attempting to start one worker within each database every autovacuum_naptime seconds. (Therefore, if the installation has N databases, a new worker will be launched every autovacuum_naptime/N seconds.)"
        }
      ]
    },
    {
      "claim_text": "Each database gets at most one worker at a time.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states there is no limit on how many workers might be in a single database.",
      "citations": [
        {
          "index": 3,
          "quote": "There is no limit on how many workers might be in a single database"
        }
      ]
    },
    {
      "claim_text": "Running workers count against max_connections.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that the number of running workers does not count towards max_connections or superuser_reserved_connections limits.",
      "citations": [
        {
          "index": 3,
          "quote": "Note that the number of running workers does not count towards max_connections or superuser_reserved_connections limits."
        }
      ]
    },
    {
      "claim_text": "Autovacuum processes partitions like ordinary tables, but it does not run ANALYZE on partitioned tables.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that autovacuum does process table partitions just like other tables, but it does not run ANALYZE on partitioned tables.",
      "citations": [
        {
          "index": 5,
          "quote": "Autovacuum does process table partitions just like other tables. Unfortunately, this means that autovacuum does not run ANALYZE on partitioned tables"
        }
      ]
    },
    {
      "claim_text": "It does not issue ANALYZE for foreign tables either.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the autovacuum daemon does not issue ANALYZE commands for foreign tables.",
      "citations": [
        {
          "index": 7,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for foreign tables"
        }
      ]
    },
    {
      "claim_text": "Normally a conflicting lock request interrupts autovacuum, and the same is true for an autovacuum that is running to prevent transaction ID wraparound.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that if the autovacuum is running to prevent transaction ID wraparound, it is not automatically interrupted.",
      "citations": [
        {
          "index": 6,
          "quote": "However, if the autovacuum is running to prevent transaction ID wraparound (i.e., the autovacuum query name in the pg_stat_activity view ends with (to prevent wraparound)), the autovacuum is not automatically interrupted."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "Standard VACUUM can run alongside normal SELECT, INSERT, UPDATE and DELETE traffic, while VACUUM FULL needs an ACCESS EXCLUSIVE lock on the table.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that standard VACUUM can run in parallel with production database operations (SELECT, INSERT, UPDATE, DELETE), while VACUUM FULL requires an ACCESS EXCLUSIVE lock and cannot be done in parallel with other use of the table.",
      "citations": [
        {
          "index": 0,
          "quote": "Also, the standard form of VACUUM can run in parallel with production database operations. (Commands such as SELECT, INSERT, UPDATE, and DELETE will continue to function normally... VACUUM FULL requires an ACCESS EXCLUSIVE lock on the table it is working on, and therefore cannot be done in parallel with other use of the table."
        }
      ]
    },
    {
      "claim_text": "VACUUM FULL is also the faster of the two because it compacts the table in a single pass.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that VACUUM FULL runs much more slowly than standard VACUUM, not faster.",
      "citations": [
        {
          "index": 0,
          "quote": "VACUUM FULL can reclaim more disk space but runs much more slowly."
        }
      ]
    },
    {
      "claim_text": "Standard VACUUM never returns space to the operating system.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says standard VACUUM does not return space to the OS 'except in the special case where one or more pages at the end of a table become entirely free and an exclusive table lock can be easily obtained.' So it is not 'never'.",
      "citations": [
        {
          "index": 2,
          "quote": "However, it will not return the space to the operating system, except in the special case where one or more pages at the end of a table become entirely free and an exclusive table lock can be easily obtained."
        }
      ]
    },
    {
      "claim_text": "VACUUM FULL, CLUSTER and the table-rewriting forms of ALTER TABLE all temporarily need extra disk space roughly equal to the size of the table, so rewriting a 50 GB table needs about another 50 GB free.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that these commands rewrite an entire new copy of the table and temporarily use extra disk space approximately equal to the size of the table.",
      "citations": [
        {
          "index": 6,
          "quote": "All these options require an ACCESS EXCLUSIVE lock. Note that they also temporarily use extra disk space approximately equal to the size of the table, since the old copies of the table and indexes can't be released until the new ones are complete."
        }
      ]
    },
    {
      "claim_text": "Since the autovacuum daemon never issues VACUUM FULL, a VACUUM FULL that shows up in your logs was not started by autovacuum.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the autovacuum daemon will never issue VACUUM FULL.",
      "citations": [
        {
          "index": 3,
          "quote": "The autovacuum daemon attempts to work this way, and in fact will never issue VACUUM FULL."
        }
      ]
    },
    {
      "claim_text": "For a table whose entire contents are deleted periodically, TRUNCATE avoids the need for a follow-up VACUUM, at the cost of violating strict MVCC semantics.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that TRUNCATE removes the entire content immediately without requiring a subsequent VACUUM, and notes the disadvantage is that strict MVCC semantics are violated.",
      "citations": [
        {
          "index": 7,
          "quote": "TRUNCATE removes the entire content of the table immediately, without requiring a subsequent VACUUM or VACUUM FULL to reclaim the now-unused disk space. The disadvantage is that strict MVCC semantics are violated."
        }
      ]
    },
    {
      "claim_text": "Installations with extremely high update rates may vacuum their busiest tables as often as every few minutes, and anyone not using autovacuum is required to run a database-wide VACUUM once a day.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says some installations vacuum as often as every few minutes, but it does not say it is 'required' to run a database-wide VACUUM once a day; it says 'a typical approach' is to schedule it once a day.",
      "citations": [
        {
          "index": 5,
          "quote": "For those not using autovacuum, a typical approach is to schedule a database-wide VACUUM once a day during a low-usage period, supplemented by more frequent vacuuming of heavily-updated tables as necessary. (Some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.)"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "Before PostgreSQL 9.4, freezing replaced a row's insertion XID with FrozenTransactionId, so on a cluster still running 9.3 frozen rows show up with an xmin of 2.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that in versions before 9.4, freezing replaced the insertion XID with FrozenTransactionId, and that rows with xmin equal to FrozenTransactionId (2) may be found in databases pg_upgrade'd from pre-9.4 versions. The claim about a cluster still running 9.3 is consistent with this, as 9.3 is before 9.4.",
      "citations": [
        {
          "index": 0,
          "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId, which was visible in the row's xmin system column."
        },
        {
          "index": 0,
          "quote": "However, rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions."
        }
      ]
    },
    {
      "claim_text": "Newer versions only set a flag bit, mainly to reduce WAL volume, and keep the original xmin, so a cluster that was pg_upgrade'd from 9.3 can never contain rows with xmin 2.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says newer versions set a flag bit and preserve the original xmin, but it also explicitly states that rows with xmin 2 may still be found in databases pg_upgrade'd from pre-9.4 versions. The claim that such a cluster can never contain rows with xmin 2 is directly contradicted. The passage does not mention reducing WAL volume as a reason.",
      "citations": [
        {
          "index": 0,
          "quote": "Newer versions just set a flag bit, preserving the row's original xmin for possible forensic use."
        },
        {
          "index": 0,
          "quote": "However, rows with xmin equal to FrozenTransactionId (2) may still be found in databases pg_upgrade'd from pre-9.4 versions."
        }
      ]
    },
    {
      "claim_text": "System catalogs can also contain rows with xmin 1, BootstrapTransactionId, which is treated as older than every normal XID.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that system catalogs may contain rows with xmin equal to BootstrapTransactionId (1), and that this special XID is treated as older than every normal XID.",
      "citations": [
        {
          "index": 1,
          "quote": "Also, system catalogs may contain rows with xmin equal to BootstrapTransactionId (1), indicating that they were inserted during the first phase of initdb."
        },
        {
          "index": 1,
          "quote": "Like FrozenTransactionId, this special XID is treated as older than every normal XID."
        }
      ]
    },
    {
      "claim_text": "pg_xact stores two bits of commit status per transaction, so the default horizon of 200 million transactions costs about 50MB, and raising autovacuum_freeze_max_age to its two-billion maximum would grow pg_xact to roughly 2GB.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says pg_xact uses two bits per transaction, and the default 200 million transactions translates to about 50MB. However, it states that setting autovacuum_freeze_max_age to its maximum of two billion would grow pg_xact to about half a gigabyte (0.5GB), not 2GB. The claim of 2GB is incorrect.",
      "citations": [
        {
          "index": 2,
          "quote": "The commit status uses two bits per transaction, so if autovacuum_freeze_max_age is set to its maximum allowed value of two billion, pg_xact can be expected to grow to about half a gigabyte"
        },
        {
          "index": 2,
          "quote": "The default, 200 million transactions, translates to about 50MB of pg_xact storage"
        }
      ]
    },
    {
      "claim_text": "Multixact member storage can grow to about 20GB before wraparound, and aggressive vacuums start running more often once it passes about half of that.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the members storage area can grow up to about 20GB before reaching wraparound, and that if the storage exceeds about 10GB (which is half of 20GB), aggressive vacuum scans occur more often.",
      "citations": [
        {
          "index": 6,
          "quote": "The members storage area can grow up to about 20GB before reaching wraparound."
        },
        {
          "index": 6,
          "quote": "if the storage occupied by multixacts members exceeds about 10GB, aggressive vacuum scans will occur more often for all tables"
        }
      ]
    },
    {
      "claim_text": "XID exhaustion and MXID exhaustion both block all write transactions.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that XID exhaustion blocks all write transactions, but MXID exhaustion only blocks a subset of write transactions, specifically those involving row locks that require an MXID. The claim that both block all write transactions is incorrect.",
      "citations": [
        {
          "index": 7,
          "quote": "XID exhaustion will block all write transactions, but MXID exhaustion will only block a subset of write transactions, specifically those that involve row locks that require an MXID."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "Because the wal-index lives in shared memory, all processes using a WAL database must be on the same host, so two processes on different machines sharing a database over NFS cannot use WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that WAL requires shared memory and does not work over a network filesystem, and that all processes must be on the same host.",
      "citations": [
        {
          "index": 0,
          "quote": "All processes using a database must be on the same host computer; WAL does not work over a network filesystem."
        },
        {
          "index": 1,
          "quote": "This is why the write-ahead log implementation will not work on a network filesystem."
        }
      ]
    },
    {
      "claim_text": "Being on the same host, however, is enough to guarantee that WAL will work.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages indicate that WAL also requires the VFS to support shared-memory methods (unless EXCLUSIVE mode is used), so being on the same host is not sufficient.",
      "citations": [
        {
          "index": 5,
          "quote": "If NORMAL locking mode is in effect for the first WAL-mode database access, then the shared-memory wal-index is created. This means that the underlying VFS must support the \"version 2\" shared-memory."
        }
      ]
    },
    {
      "claim_text": "Since there is only one WAL file, two writers can never be writing at the same moment, even though readers can run alongside a writer; this single-writer limit can be lifted with BEGIN CONCURRENT.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages confirm that there is only one writer at a time, but they do not mention BEGIN CONCURRENT or any way to lift the single-writer limit.",
      "citations": []
    },
    {
      "claim_text": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access, and in that case it stays in EXCLUSIVE mode until it leaves WAL journal mode.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that WAL can be used without shared memory if EXCLUSIVE locking mode is set before first access, and that the mode remains EXCLUSIVE until leaving WAL mode.",
      "citations": [
        {
          "index": 3,
          "quote": "WAL databases can be created, read, and written even if shared memory is unavailable as long as the locking_mode is set to EXCLUSIVE before the first attempted access."
        },
        {
          "index": 4,
          "quote": "the database connection remains in EXCLUSIVE mode as long as the journal mode is WAL; attempts to change the locking mode using \"PRAGMA locking_mode=NORMAL;\" are no-ops. The only way to change out of EXCLUSIVE locking mode is to first change out of WAL journal mode."
        }
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync and the checkpoint is the only operation that issues a sync; with FULL, every commit syncs the WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that with NORMAL, the checkpoint is the only sync operation, and with FULL, writers sync the WAL on every commit.",
      "citations": [
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL but omit this sync if PRAGMA synchronous is set to NORMAL."
        },
        {
          "index": 7,
          "quote": "Note that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation"
        }
      ]
    },
    {
      "claim_text": "Running the checkpoint in a separate thread therefore guarantees that the main thread never blocks on a sync, whatever the synchronous setting.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages state that with NORMAL, running checkpoint in a separate thread prevents the main thread from blocking on sync, but with FULL, commits sync the WAL, so the main thread may still block on sync.",
      "citations": [
        {
          "index": 7,
          "quote": "If an application therefore runs checkpoint in a separate thread or process, the main thread or process that is doing database queries and updates will never block on a sync operation."
        },
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "If you increment a counter 100 times, the AOF holds 100 entries even though 99 of them are unnecessary.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that incrementing a counter 100 times results in 100 entries in the AOF, with 99 being unnecessary.",
      "citations": [
        {
          "index": 3,
          "quote": "if you are incrementing a counter 100 times, you'll end up with a single key in your dataset containing the final value, but 100 entries in your AOF. 99 of those entries are not needed to rebuild the current state."
        }
      ]
    },
    {
      "claim_text": "After a rewrite that key can be rebuilt from a single command.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says that BGREWRITEAOF writes the shortest sequence of commands needed to rebuild the current dataset, implying a single command for a single key.",
      "citations": [
        {
          "index": 4,
          "quote": "Redis will write the shortest sequence of commands needed to rebuild the current dataset in memory."
        }
      ]
    },
    {
      "claim_text": "On Redis 2.2 you have to run BGREWRITEAOF yourself, while Redis 2.6 can trigger log rewriting automatically.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says Redis 2.4 can trigger log rewriting automatically, not 2.6.",
      "citations": [
        {
          "index": 4,
          "quote": "If you're using the AOF with Redis 2.2 you'll need to run BGREWRITEAOF from time to time. Since Redis 2.4 is able to trigger log rewriting automatically"
        }
      ]
    },
    {
      "claim_text": "Redis 2.4 and later never run an AOF rewrite and an RDB snapshot at the same time.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that Redis >= 2.4 avoids triggering an AOF rewrite when an RDB snapshot is in progress, and vice versa.",
      "citations": [
        {
          "index": 7,
          "quote": "Redis >= 2.4 makes sure to avoid triggering an AOF rewrite when an RDB snapshotting operation is already in progress, or allowing a BGSAVE while the AOF rewrite is in progress."
        }
      ]
    },
    {
      "claim_text": "If you request BGREWRITEAOF while a snapshot is running, Redis schedules it and starts it once the snapshot completes.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly describes this behavior.",
      "citations": [
        {
          "index": 8,
          "quote": "When snapshotting is in progress and the user explicitly requests a log rewrite operation using BGREWRITEAOF the server will reply with an OK status code telling the user the operation is scheduled, and the rewrite will start once the snapshotting is completed."
        }
      ]
    },
    {
      "claim_text": "With appendfsync everysec you can lose up to one second of writes.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that with everysec policy you may lose 1 second of data.",
      "citations": [
        {
          "index": 5,
          "quote": "appendfsync everysec: fsync every second. Fast enough ... and you may lose 1 second of data if there is a disaster."
        }
      ]
    },
    {
      "claim_text": "With appendfsync always no writes are lost in any failure scenario.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says appendfsync always is 'very safe' but does not guarantee no writes are lost in any failure scenario; it only says it is very safe.",
      "citations": [
        {
          "index": 5,
          "quote": "appendfsync always: fsync every time new commands are appended to the AOF. Very very slow, very safe."
        }
      ]
    },
    {
      "claim_text": "RDB forks less often than AOF does.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says AOF forks less frequently than RDB, not the other way around.",
      "citations": [
        {
          "index": 1,
          "quote": "AOF also needs to fork() but less frequently and you can tune how often you want to rewrite your logs without any trade-off on durability."
        }
      ]
    },
    {
      "claim_text": "When both AOF and RDB are enabled, Redis rebuilds the dataset from the AOF on restart rather than from the RDB file.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the AOF file is used to reconstruct the dataset when both are enabled.",
      "citations": [
        {
          "index": 9,
          "quote": "In the case both AOF and RDB persistence are enabled and Redis restarts the AOF file will be used to reconstruct the original dataset since it is guaranteed to be the most complete."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "A common backup scheme keeps hourly RDB snapshots for the latest 48 hours and daily snapshots for one or two months, which means up to 48 hourly files and as many as about 60 daily files.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages explicitly describe this backup scheme, including the number of hourly and daily snapshots.",
      "citations": [
        {
          "index": 0,
          "quote": "for instance you can take hourly snapshots for the latest 48 hours, and daily snapshots for one or two months."
        }
      ]
    },
